CREATE TABLE public.user_access (user_id uuid PRIMARY KEY, access_level text NOT NULL DEFAULT 'funcionario' CHECK (access_level IN ('socios','gerentes','rh','financas','marketing','funcionario')), area text, position text, sales_enabled boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'ativo' CHECK (status IN ('ativo','suspenso','exonerado')), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.user_access TO authenticated; GRANT ALL ON public.user_access TO service_role;
ALTER TABLE public.user_access ENABLE ROW LEVEL SECURITY;
INSERT INTO public.user_access(user_id,access_level,sales_enabled) SELECT user_id, CASE WHEN bool_or(role::text IN ('socio','socio_fundador')) THEN 'socios' WHEN bool_or(role::text='gerente') THEN 'gerentes' ELSE 'funcionario' END, bool_or(role::text='vendedor') FROM public.user_roles GROUP BY user_id;
CREATE FUNCTION public.access_level_for(_id uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN a.status='ativo' THEN a.access_level ELSE 'restrito' END FROM public.user_access a WHERE a.user_id=_id $$;
CREATE FUNCTION public.is_partner(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(public.access_level_for(_id)='socios',false) $$;
CREATE FUNCTION public.area_access(_id uuid,_area text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(public.is_partner(_id) OR public.access_level_for(_id)=_area OR (public.access_level_for(_id)='gerentes' AND _area IN ('projetos','financas','comercial')),false) $$;
CREATE OR REPLACE FUNCTION public.is_gestao(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(public.access_level_for(_user_id) IN ('socios','gerentes'),false) $$;
CREATE OR REPLACE FUNCTION public.can_sell(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_access WHERE user_id=_user_id AND status='ativo' AND (access_level IN ('socios','gerentes') OR (access_level='funcionario' AND sales_enabled))) $$;
CREATE POLICY "access self or administrators" ON public.user_access FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_partner(auth.uid()) OR public.access_level_for(auth.uid())='gerentes');
CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM pg_advisory_xact_lock(8521001); INSERT INTO public.profiles(id,full_name,email) VALUES(new.id,coalesce(new.raw_user_meta_data->>'full_name',new.email),new.email); IF NOT EXISTS(SELECT 1 FROM public.user_access) THEN INSERT INTO public.user_roles(user_id,role) VALUES(new.id,'socio_fundador'),(new.id,'gerente'); INSERT INTO public.user_access(user_id,access_level) VALUES(new.id,'socios'); ELSE INSERT INTO public.user_access(user_id,access_level) VALUES(new.id,'funcionario'); END IF; RETURN new; END $$;
ALTER TABLE public.employees ADD COLUMN doc_issued date, ADD COLUMN doc_expires date, ADD COLUMN doc_path text, ADD COLUMN dependents integer NOT NULL DEFAULT 0, ADD COLUMN contract_type text NOT NULL DEFAULT 'indeterminado', ADD COLUMN area text, ADD COLUMN birth_date date, ADD COLUMN gender text;
CREATE UNIQUE INDEX employees_linked_user ON public.employees(user_id) WHERE user_id IS NOT NULL;
ALTER TABLE public.absences ADD COLUMN occurred_at timestamptz, ADD COLUMN submitted_at timestamptz, ADD COLUMN justification text, ADD COLUMN decision text NOT NULL DEFAULT 'pendente', ADD COLUMN decided_by uuid, ADD COLUMN decided_at timestamptz;
UPDATE public.absences SET occurred_at=(absence_date::text || ' 00:00:00 Africa/Maputo')::timestamptz;
ALTER TABLE public.absences ALTER COLUMN occurred_at SET DEFAULT now();
DROP POLICY "absence self insert" ON public.absences;
DROP POLICY "gestao all" ON public.absences;
CREATE POLICY "hr absence management" ON public.absences FOR ALL TO authenticated USING(public.area_access(auth.uid(),'rh')) WITH CHECK(public.area_access(auth.uid(),'rh'));
DROP POLICY "gestao all" ON public.employees;
CREATE POLICY "hr employees management" ON public.employees FOR ALL TO authenticated USING(public.area_access(auth.uid(),'rh')) WITH CHECK(public.area_access(auth.uid(),'rh'));
CREATE POLICY "finance payroll employees" ON public.employees FOR SELECT TO authenticated USING(public.area_access(auth.uid(),'financas'));
DROP POLICY "gestao all" ON public.evaluations;
CREATE POLICY "hr evaluations" ON public.evaluations FOR ALL TO authenticated USING(public.area_access(auth.uid(),'rh')) WITH CHECK(public.area_access(auth.uid(),'rh'));
CREATE POLICY "self evaluations" ON public.evaluations FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.employees e WHERE e.id=employee_id AND e.user_id=auth.uid()));
DROP POLICY "gestao all" ON public.vacations;
CREATE POLICY "hr vacations" ON public.vacations FOR ALL TO authenticated USING(public.area_access(auth.uid(),'rh')) WITH CHECK(public.area_access(auth.uid(),'rh'));
CREATE POLICY "self vacations" ON public.vacations FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.employees e WHERE e.id=employee_id AND e.user_id=auth.uid()));
DROP POLICY "gestao all" ON public.shareholders; DROP POLICY "gestao all" ON public.resolutions; DROP POLICY "gestao all" ON public.resolution_votes;
CREATE POLICY "partner shareholders" ON public.shareholders FOR ALL TO authenticated USING(public.is_partner(auth.uid())) WITH CHECK(public.is_partner(auth.uid()));
CREATE POLICY "partner resolutions" ON public.resolutions FOR ALL TO authenticated USING(public.is_partner(auth.uid())) WITH CHECK(public.is_partner(auth.uid()));
CREATE POLICY "partner votes read" ON public.resolution_votes FOR SELECT TO authenticated USING(public.is_partner(auth.uid()));
ALTER TABLE public.resolutions ADD COLUMN qualified_quorum boolean NOT NULL DEFAULT true;
ALTER TABLE public.shareholders ADD COLUMN invested numeric NOT NULL DEFAULT 0, ADD COLUMN email text, ADD COLUMN contact text, ADD COLUMN doc_number text;
ALTER TABLE public.projects ADD COLUMN investment numeric NOT NULL DEFAULT 0, ADD COLUMN area text, ADD COLUMN submitted_by uuid DEFAULT auth.uid(), ADD COLUMN submitted_at date NOT NULL DEFAULT CURRENT_DATE, ADD COLUMN uses_company_resources boolean NOT NULL DEFAULT true;
ALTER TABLE public.tasks ADD COLUMN scope text NOT NULL DEFAULT 'geral' CHECK(scope IN ('geral','area','funcionario')), ADD COLUMN area text, ADD COLUMN assigned_user_id uuid, ADD COLUMN created_by uuid DEFAULT auth.uid(), ADD COLUMN postponed_reason text;
DROP POLICY "gestao all" ON public.tasks;
CREATE POLICY "scoped tasks read" ON public.tasks FOR SELECT TO authenticated USING(public.is_gestao(auth.uid()) OR (public.access_level_for(auth.uid()) IS NOT NULL AND public.access_level_for(auth.uid())<>'restrito' AND (scope='geral' OR assigned_user_id=auth.uid() OR (scope='area' AND area=(SELECT a.area FROM public.user_access a WHERE a.user_id=auth.uid())))));
CREATE POLICY "scoped task management" ON public.tasks FOR ALL TO authenticated USING(public.is_gestao(auth.uid()) OR (public.access_level_for(auth.uid()) IN ('rh','financas','marketing') AND scope='area' AND area=(SELECT a.area FROM public.user_access a WHERE a.user_id=auth.uid()))) WITH CHECK(public.is_gestao(auth.uid()) OR (public.access_level_for(auth.uid()) IN ('rh','financas','marketing') AND scope='area' AND area=(SELECT a.area FROM public.user_access a WHERE a.user_id=auth.uid())));
DROP POLICY "gestao all" ON public.budgets; DROP POLICY "gestao all" ON public.debts; DROP POLICY "gestao all" ON public.debt_payments;
CREATE POLICY "finance budgets" ON public.budgets FOR ALL TO authenticated USING(public.area_access(auth.uid(),'financas')) WITH CHECK(public.area_access(auth.uid(),'financas'));
CREATE POLICY "finance debts" ON public.debts FOR ALL TO authenticated USING(public.area_access(auth.uid(),'financas')) WITH CHECK(public.area_access(auth.uid(),'financas'));
CREATE POLICY "finance debt payments" ON public.debt_payments FOR ALL TO authenticated USING(public.area_access(auth.uid(),'financas')) WITH CHECK(public.area_access(auth.uid(),'financas'));
DROP POLICY "products manage direcao" ON public.products;
CREATE POLICY "commercial price management" ON public.products FOR ALL TO authenticated USING(public.area_access(auth.uid(),'comercial')) WITH CHECK(public.area_access(auth.uid(),'comercial'));
CREATE TABLE public.company_contacts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), position text NOT NULL, name text NOT NULL, contact text, email text);
GRANT SELECT ON public.company_contacts TO authenticated; GRANT INSERT,UPDATE,DELETE ON public.company_contacts TO authenticated; GRANT ALL ON public.company_contacts TO service_role;
ALTER TABLE public.company_contacts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "employee contacts" ON public.company_contacts FOR SELECT TO authenticated USING(public.access_level_for(auth.uid()) IS NOT NULL);
CREATE POLICY "contacts manage" ON public.company_contacts FOR ALL TO authenticated USING(public.is_partner(auth.uid()) OR public.access_level_for(auth.uid())='gerentes') WITH CHECK(public.is_partner(auth.uid()) OR public.access_level_for(auth.uid())='gerentes');
CREATE TABLE public.employee_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),employee_id uuid NOT NULL REFERENCES public.employees(id),kind text NOT NULL CHECK(kind IN ('ferias','dispensa','reclamacao','sindicato')),details text NOT NULL,start_date date,days numeric,status text NOT NULL DEFAULT 'pendente',created_at timestamptz NOT NULL DEFAULT now(),decided_by uuid,decided_at timestamptz);
GRANT SELECT,INSERT ON public.employee_requests TO authenticated; GRANT ALL ON public.employee_requests TO service_role;
ALTER TABLE public.employee_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY "requests own read" ON public.employee_requests FOR SELECT TO authenticated USING(public.area_access(auth.uid(),'rh') OR EXISTS(SELECT 1 FROM public.employees e WHERE e.id=employee_id AND e.user_id=auth.uid()));
CREATE POLICY "requests own insert" ON public.employee_requests FOR INSERT TO authenticated WITH CHECK(status='pendente' AND decided_by IS NULL AND decided_at IS NULL AND EXISTS(SELECT 1 FROM public.employees e WHERE e.id=employee_id AND e.user_id=auth.uid()) AND public.access_level_for(auth.uid()) IS NOT NULL);
CREATE TABLE public.payroll_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),period date NOT NULL,employee_id uuid NOT NULL REFERENCES public.employees(id),base numeric NOT NULL,absence_deduction numeric NOT NULL DEFAULT 0,inss_worker numeric NOT NULL,inss_employer numeric NOT NULL,union_deduction numeric NOT NULL DEFAULT 0,irps numeric,net numeric,thirteenth_pct numeric NOT NULL DEFAULT 100,status text NOT NULL DEFAULT 'rascunho',hr_signed_by uuid,hr_signed_at timestamptz,employee_signed_by uuid,employee_signed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(period,employee_id));
GRANT SELECT ON public.payroll_runs TO authenticated; GRANT ALL ON public.payroll_runs TO service_role;
ALTER TABLE public.payroll_runs ENABLE ROW LEVEL SECURITY;
CREATE POLICY "payroll authorized reads" ON public.payroll_runs FOR SELECT TO authenticated USING(public.area_access(auth.uid(),'rh') OR public.area_access(auth.uid(),'financas') OR EXISTS(SELECT 1 FROM public.employees e WHERE e.id=employee_id AND e.user_id=auth.uid()));
CREATE TABLE public.payroll_payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),run_id uuid NOT NULL REFERENCES public.payroll_runs(id),amount numeric NOT NULL,proof_path text NOT NULL,reason text,paid_by uuid NOT NULL,paid_at timestamptz NOT NULL DEFAULT now(),event_key uuid NOT NULL UNIQUE);
GRANT SELECT ON public.payroll_payments TO authenticated; GRANT ALL ON public.payroll_payments TO service_role;
ALTER TABLE public.payroll_payments ENABLE ROW LEVEL SECURITY;
CREATE POLICY "payroll payment read" ON public.payroll_payments FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.payroll_runs r WHERE r.id=run_id));
CREATE TABLE public.cash_movements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),direction text NOT NULL CHECK(direction IN ('entrada','saida')),category text NOT NULL,description text NOT NULL,amount numeric NOT NULL CHECK(amount>0),proof_path text NOT NULL,project_id uuid REFERENCES public.projects(id),created_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now(),event_key uuid NOT NULL UNIQUE);
GRANT SELECT,INSERT ON public.cash_movements TO authenticated; GRANT ALL ON public.cash_movements TO service_role;
ALTER TABLE public.cash_movements ENABLE ROW LEVEL SECURITY;
CREATE POLICY "finance movements read" ON public.cash_movements FOR SELECT TO authenticated USING(public.area_access(auth.uid(),'financas'));
CREATE POLICY "finance movements insert" ON public.cash_movements FOR INSERT TO authenticated WITH CHECK(public.area_access(auth.uid(),'financas') AND created_by=auth.uid());
CREATE TABLE public.strategic_reserves(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,kind text NOT NULL CHECK(kind IN ('recorrente','nao_recorrente','semi_recorrente')),target numeric NOT NULL DEFAULT 0,balance numeric NOT NULL DEFAULT 0,confidential boolean NOT NULL DEFAULT true,hidden boolean NOT NULL DEFAULT false);
GRANT SELECT,INSERT,UPDATE ON public.strategic_reserves TO authenticated; GRANT ALL ON public.strategic_reserves TO service_role;
ALTER TABLE public.strategic_reserves ENABLE ROW LEVEL SECURITY;
CREATE POLICY "reserve visible reads" ON public.strategic_reserves FOR SELECT TO authenticated USING(public.is_partner(auth.uid()) OR (NOT confidential AND public.area_access(auth.uid(),'financas')));
CREATE POLICY "partners reserves manage" ON public.strategic_reserves FOR ALL TO authenticated USING(public.is_partner(auth.uid())) WITH CHECK(public.is_partner(auth.uid()));
CREATE TABLE public.audit_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid NOT NULL,action text NOT NULL,target_id uuid,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.audit_events TO authenticated; GRANT ALL ON public.audit_events TO service_role;
ALTER TABLE public.audit_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY "partner audit read" ON public.audit_events FOR SELECT TO authenticated USING(public.is_partner(auth.uid()));
CREATE FUNCTION public.submit_absence_proof(_absence uuid,_proof text,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.absences; BEGIN SELECT * INTO a FROM public.absences WHERE id=_absence FOR UPDATE; IF NOT EXISTS(SELECT 1 FROM public.employees e WHERE e.id=a.employee_id AND e.user_id=auth.uid()) THEN RAISE EXCEPTION 'Sem permissão'; END IF; IF a.submitted_at IS NOT NULL OR now()<a.occurred_at OR now()>a.occurred_at+interval '48 hours' THEN RAISE EXCEPTION 'Prazo de 48 horas encerrado'; END IF; IF length(trim(_reason))<3 OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='comprovativos' AND name=_proof AND owner_id=auth.uid()::text) THEN RAISE EXCEPTION 'Comprovativo e justificação obrigatórios'; END IF; UPDATE public.absences SET proof_path=_proof,justification=_reason,submitted_at=now(),decision='pendente' WHERE id=_absence; END $$;
CREATE FUNCTION public.decide_absence(_absence uuid,_decision text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.absences; BEGIN SELECT * INTO a FROM public.absences WHERE id=_absence FOR UPDATE; IF NOT(public.area_access(auth.uid(),'rh') OR EXISTS(SELECT 1 FROM public.employees e JOIN public.user_access u ON u.area=e.area WHERE e.id=a.employee_id AND u.user_id=auth.uid() AND u.status='ativo' AND u.access_level IN ('gerentes','rh','financas','marketing'))) THEN RAISE EXCEPTION 'Sem permissão'; END IF; IF _decision NOT IN ('aprovada','rejeitada') OR a.submitted_at IS NULL THEN RAISE EXCEPTION 'Justificação não submetida'; END IF; UPDATE public.absences SET decision=_decision,decided_by=auth.uid(),decided_at=now() WHERE id=_absence; END $$;
CREATE FUNCTION public.decide_employee_request(_id uuid,_status text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.employee_requests; BEGIN IF NOT public.area_access(auth.uid(),'rh') THEN RAISE EXCEPTION 'Sem permissão'; END IF; SELECT * INTO r FROM public.employee_requests WHERE id=_id FOR UPDATE; IF r.status<>'pendente' OR _status NOT IN ('aprovado','rejeitado') THEN RAISE EXCEPTION 'Decisão inválida'; END IF; UPDATE public.employee_requests SET status=_status,decided_by=auth.uid(),decided_at=now() WHERE id=_id; IF _status='aprovado' AND r.kind='sindicato' THEN UPDATE public.employees SET union_member=true WHERE id=r.employee_id; END IF; IF _status='aprovado' AND r.kind='ferias' THEN IF r.days<=0 OR r.start_date IS NULL THEN RAISE EXCEPTION 'Indique dias e data'; END IF; INSERT INTO public.vacations(employee_id,start_date,days) VALUES(r.employee_id,r.start_date,r.days); END IF; END $$;
CREATE FUNCTION public.complete_task(_id uuid,_done boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF public.access_level_for(auth.uid())='restrito' THEN RAISE EXCEPTION 'Acesso restrito'; END IF; UPDATE public.tasks SET done=_done WHERE id=_id AND (public.is_gestao(auth.uid()) OR assigned_user_id=auth.uid()); IF NOT FOUND THEN RAISE EXCEPTION 'Sem permissão'; END IF; END $$;
REVOKE ALL ON FUNCTION public.submit_absence_proof(uuid,text,text),public.decide_absence(uuid,text),public.decide_employee_request(uuid,text),public.complete_task(uuid,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.submit_absence_proof(uuid,text,text),public.decide_absence(uuid,text),public.decide_employee_request(uuid,text),public.complete_task(uuid,boolean) TO authenticated;
DROP POLICY "comprovativos upload" ON storage.objects;
CREATE POLICY "comprovativos upload" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='comprovativos' AND owner_id=auth.uid()::text AND (storage.foldername(name))[2]=auth.uid()::text AND ((storage.foldername(name))[1] IN ('faltas','documentos') OR ((storage.foldername(name))[1] IN ('dividas','movimentos','salarios') AND public.area_access(auth.uid(),'financas')) OR ((storage.foldername(name))[1]='vendas' AND public.can_sell(auth.uid()))));
DROP POLICY "comprovativos read" ON storage.objects;
CREATE POLICY "comprovativos read" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='comprovativos' AND (owner_id=auth.uid()::text OR public.is_partner(auth.uid()) OR ((storage.foldername(name))[1] IN ('faltas','documentos') AND public.area_access(auth.uid(),'rh')) OR ((storage.foldername(name))[1] IN ('dividas','movimentos','salarios','vendas') AND public.area_access(auth.uid(),'financas'))));
COMMENT ON TABLE public.user_roles IS 'Legacy role storage retained for compatibility and founding-partner status; user_access owns the six access levels.';